import { Request, Response } from "express";

const ALLOWED_HOSTS = new Set(["images.example-cdn.com", "static.example.com"]);

export async function fetchRemote(req: Request, res: Response) {
  let target: URL;
  try {
    target = new URL(String(req.query.url));
  } catch {
    return res.status(400).end();
  }
  if (target.protocol !== "https:" || !ALLOWED_HOSTS.has(target.hostname)) {
    return res.status(400).end();
  }
  const upstream = await axios.get(target.toString(), { timeout: 5000, maxRedirects: 0 });
  res.status(upstream.status).send(upstream.data);
}

const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

function merge(target, source) {
  for (const key of Object.keys(source)) {
    if (FORBIDDEN.has(key)) continue;
    if (typeof source[key] === "object" && source[key] !== null) {
      if (!Object.hasOwn(target, key)) target[key] = Object.create(null);
      merge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

