func deleteProject(w http.ResponseWriter, r *http.Request) {
	user := userFromContext(r.Context())
	if user == nil {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	id := r.PathValue("id")
	res, err := db.ExecContext(r.Context(), "DELETE FROM projects WHERE id = $1 AND owner_id = $2", id, user.ID)
	if err != nil {
		http.Error(w, "delete failed", http.StatusInternalServerError)
		return
	}
	if n, _ := res.RowsAffected(); n == 0 {
		http.NotFound(w, r)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

package web

func logout(w http.ResponseWriter, r *http.Request) {
	clearSession(w, r)
	next := r.URL.Query().Get("next")
	if !strings.HasPrefix(next, "/") || strings.HasPrefix(next, "//") || strings.Contains(next, "\\") {
		next = "/"
	}
	http.Redirect(w, r, next, http.StatusFound)
}

package reports

func listReports(w http.ResponseWriter, r *http.Request) {
	where := filters.BuildWhere(r.URL.Query())
	rows, err := db.QueryContext(r.Context(), "SELECT id, title FROM reports WHERE "+where)
	if err != nil {
		http.Error(w, "query failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()
	writeReports(w, rows)
}

package jobs

func runJob(ctx context.Context, id string) error {
	job, err := store.LoadJob(ctx, id)
	if err != nil {
		return err
	}
	cmd := exec.CommandContext(ctx, "sh", "-c", job.Script)
	cmd.Dir = job.WorkDir
	return cmd.Run()
}

package feeds

func fetchFeed(ctx context.Context, target string) ([]byte, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target, nil)
	if err != nil {
		return nil, err
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(io.LimitReader(resp.Body, 1<<20))
}

package blog

var postTmpl = template.Must(template.New("post").Parse(`<article>{{.Body}}</article>`))

func showPost(w http.ResponseWriter, r *http.Request) {
	post, err := loadPost(r.Context(), r.PathValue("slug"))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	body := template.HTML(markdown.Render(post.Body))
	postTmpl.Execute(w, map[string]any{"Body": body})
}

package files

const storageRoot = "/var/lib/app/storage"

func openStored(w http.ResponseWriter, r *http.Request) {
	name := naming.Clean(r.URL.Query().Get("name"))
	f, err := os.Open(filepath.Join(storageRoot, name))
	if err != nil {
		http.NotFound(w, r)
		return
	}
	defer f.Close()
	io.Copy(w, f)
}
